"""Normalize emphasis in the HTML generated by the MediaWiki renderer."""

from html.parser import HTMLParser

_EMPHASIS = ("b", "i")


class _EmphasisNormalizer(HTMLParser):
    def __init__(self, *, preserve_bold: bool, preserve_italic: bool) -> None:
        super().__init__(convert_charrefs=False)
        self._preserve = {"b": preserve_bold, "i": preserve_italic}
        self._depth = dict.fromkeys(_EMPHASIS, 0)
        self._open: tuple[str, ...] = ()
        self._whitespace: list[str] = []
        self._output: list[str] = []

    def _styles(self, styles: tuple[str, ...]) -> None:
        shared = 0
        for before, after in zip(self._open, styles):
            if before != after:
                break
            shared += 1
        self._output.extend(f"</{tag}>" for tag in reversed(self._open[shared:]))
        self._output.extend(f"<{tag}>" for tag in styles[shared:])
        self._open = styles

    def _flush_whitespace(self) -> None:
        self._output.extend(self._whitespace)
        self._whitespace.clear()

    def _content(self, value: str) -> None:
        styles = tuple(
            tag for tag in _EMPHASIS if self._depth[tag] and self._preserve[tag]
        )
        if self._whitespace and styles != self._open:
            self._styles(())
        self._flush_whitespace()
        self._styles(styles)
        self._output.append(value)

    def _boundary(self, markup: str) -> None:
        self._styles(())
        self._flush_whitespace()
        self._output.append(markup)

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in self._depth:
            self._depth[tag] += 1
        elif markup := self.get_starttag_text():
            self._boundary(markup)

    def handle_startendtag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if markup := self.get_starttag_text():
            self._boundary(markup)

    def handle_endtag(self, tag: str) -> None:
        if tag in self._depth:
            self._depth[tag] -= 1
        else:
            self._boundary(f"</{tag}>")

    def handle_data(self, data: str) -> None:
        if data.isspace():
            self._whitespace.append(data)
        else:
            self._content(data)

    def handle_entityref(self, name: str) -> None:
        self._content(f"&{name};")

    def handle_charref(self, name: str) -> None:
        self._content(f"&#{name};")

    def finish(self) -> str:
        self.close()
        self._boundary("")
        return "".join(self._output)


def normalize_emphasis(html: str, *, preserve_bold: bool, preserve_italic: bool) -> str:
    """Merge equal emphasis around inline text and keep other HTML boundaries."""
    normalizer = _EmphasisNormalizer(
        preserve_bold=preserve_bold, preserve_italic=preserve_italic
    )
    normalizer.feed(html)
    return normalizer.finish()
